            aggFn: 'avg',
            valueExpression: 'Duration',
            aggCondition: '',
            alias: 'weighted_avg',
          },
          {
            aggFn: 'min',
            valueExpression: 'Duration',
            aggCondition: '',
            alias: 'min_duration',
          },
          {
            aggFn: 'count_distinct',
            valueExpression: 'TraceId',
            aggCondition: '',
            alias: 'unique_traces',
