      const sql = await builder.build();

      expect(sql).toContain("hasAllTokens(lower(Body), lower('FOO'))");
      expect(sql).toContain("NOT (hasAllTokens(lower(Body), lower('BAR')))");
      expect(sql).toContain("hasAllTokens(lower(Body), lower('BAZ'))");
