      english: '(Events.JSONAttributes.message contains "key1 key2")',
    },
    {
      lucene: 'Events.JSONAttributes.message:*',
      sql: '(arrayExists(el -> notEmpty(toString(el.`message`)) = 1, Events.JSONAttributes))',
      english:
